from locust import HttpUser, task, between

class Shopper(HttpUser):
    wait_time = between(1, 3)

    @task(5)
    def browse(self):
        self.client.get("/items")

    @task(1)
    def checkout(self):
        self.client.post("/orders", json={"sku": "A1", "qty": 1})

